{
      type: "object",
      properties: {
        action: {
          type: "string",
          enum: [...SPACES_ACTIONS],
          description:
            'Required. Example: {"action": "health"}',
        },
        space: { type: "string", description: "Space id; session default (sources/jobs: personal). Required for rename/archive/leave/handover. Never rebinds" },
        name: { type: "string", description: "create, rename: the space's name" },
        view: { type: "string", enum: [...INVENTORY_VIEWS], description: "inventory: required read projection" },
        cursor: { type: "string", maxLength: 512, description: "Read cursor; same query/scope" },
        area: { type: "string", enum: [...CONSOLE_AREAS], description: "console: required area; human link only, never a submitted request or completion" },
        path: { type: "string", maxLength: 256, description: "summaries: path from list for full body; omit to list. Own personal space/current agent only" },
        user: { type: "string", description: "handover: existing member's email or user id" },
        skill: {
          type: "object",
          description: "skills: stored skills, not local workflows. get/versions need id; search needs query",
          properties: {
            op: { type: "string", enum: ["list", "get", "search", "versions"] },
            id: { type: "string", maxLength: 200 },
            query: { type: "string", maxLength: 2048 },
            offset: { type: "integer", minimum: 0, maximum: 100000, description: "list/versions: offset, default 0; same space/id, not a snapshot" },
          },
          required: ["op"],
          additionalProperties: false,
        },
        restore: { type: "boolean", description: "archive: true unarchives the space" },
        bind: {
          type: "object",
          description: 'current: session binding. sources: request account proof; person confirms',
          properties: {
            space: { type: "string", description: 'current: "personal" or a space id from list' },
            source: { type: "string", description: "sources: plugin namespace, such as gmail or slack" },
            account: { type: "string", description: 'sources: the account within it; default "default"' },
          },
          additionalProperties: false,
        },
        unbind: {
          type: "object",
          description: "sources: preview account unbind/event deletion unless confirm",
          properties: {
            source: { type: "string", description: "The source" },
            account: { type: "string", description: 'The account; default "default"' },
          },
          required: ["source"],
          additionalProperties: false,
        },
        confirm: { type: "boolean", description: "unbind/archive/leave/handover: true after agreement; else preview" },
        job: {
          type: "object",
          description: 'jobs: list/templates/hosts need no id; diff/items need id; diff accepts version. Read cursor uses same query. Draft never runs; activate/delete are human links',
          properties: {
            op: { type: "string", enum: [...JOB_OPS] },
            id: { type: "string" },
            version: { type: "integer", minimum: 1, description: "diff: version; omitted means draft" },
            template: { type: "string" },
            project: { type: "string" },
            account: { type: "string" },
            scope: { type: "object", additionalProperties: true },
            every: { type: "string" },
            max_lines: { type: "integer", minimum: 1, maximum: 500 },
            limit: { type: "integer", minimum: 1, maximum: 100 },
          },
          required: ["op"],
          additionalProperties: false,
        },
        decide: {
          type: "object",
          description: "review: decide one proposal on request",
          properties: {
            id: { type: "string", description: "The proposal id" },
            decision: { type: "string", enum: [...DECISIONS], description: "accept applies it; edit applies payload instead; reject drops it" },
            reason: { type: "string", description: "Why; kept on the proposal" },
            payload: { type: "string", description: "edit: the text to apply instead" },
          },
          required: ["id", "decision"],
          additionalProperties: false,
        },
        limit: { type: "integer", minimum: 1, maximum: 100, description: `review: proposals to list (default ${REVIEW_LIMIT})` },
      },
      required: ["action"],
      additionalProperties: false,
    }

{
      type: "object",
      properties: {
        action: {
          type: "string",
          enum: [...WIKI_READ_ACTIONS, ...WIKI_WRITE_ACTIONS],
          description:
            'Required. documents: filenames, 50/page. graph: topology, max400 nodes/1200 edges/100 communities. Example: {"action":"search","query":"onboarding"}',
        },
        query: { type: "string", description: "Search query (required for action=search)" },
        cursor: { type: "string", maxLength: 4096, description: "documents: previous cursor; same wiki/space" },
        knowledge_id: {
          type: "string",
          description: "search: wiki/code-graph id from list, not an ACL asset id",
        },
        wiki_id: {
          type: "string",
          description:
            "Wiki id; optional with one visible wiki, except whole-wiki deletion always names it",
        },
        name: { type: "string", description: "Human-readable wiki name for action=create" },
        filename: {
          type: "string",
          description: `Flat source filename, required for write and append; create defaults to ${DEFAULT_FILE}. No folders/traversal. read/delete also accept it`,
        },
        content: {
          type: "string",
          description:
            "Supplied Markdown for create/write/append; write replaces the source. Pages use mem_page; tasks use mem_commitments",
        },
        ingest: {
          type: "boolean",
          description:
            "Ignored: ingestion starts automatically after the last write in a burst",
        },
        ref: {
          type: "string",
          description:
            "read/delete: hit's path or generated page id; read tries its source first",
        },
        confirm: {
          type: "boolean",
          description:
            "delete: false previews; true uses host policy/service checks and readback. Pass true only when the person asked; one you propose is offered, never deleted",
        },
        path: { type: "string", description: "Same as ref: the page path a search hit shows" },
        visibility: {
          type: "string",
          enum: ["auto", "private", "team"],
          description:
            "auto (default), as mem_recall: the session's space. private: own personal. team: bound/named shared. Never rebinds",
        },
        type: {
          type: "string",
          enum: ["wiki", "code-graph", "all"],
          description: "Which knowledge list and search cover: wiki, code-graph, or all (the default)",
        },
        space: { type: "string", description: "Space id to browse or write (control plane); defaults to the active space" },
      },
      required: ["action"],
      additionalProperties: false,
    }

{
      type: "object",
      properties: {
        id: { type: "string", pattern: "^rec_[0-9A-HJKMNP-TV-Z]{26}$", description: "Required memory rec_ id from recall/remember; not a page/atom/turn" },
        space: { type: "string", description: "Space id/personal/shared; session default, never rebinds" },
      },
      required: ["id"],
      additionalProperties: false,
    }

{
      type: "object",
      properties: {
        action: { type: "string", enum: Object.keys(CODE_READS), description: "Required read operation" },
        graph_id: { type: "string", pattern: "^[A-Za-z0-9][A-Za-z0-9_.:-]{2,127}$", description: "Required code-graph id from wiki list; not an ACL asset id" },
        query: { type: "string", maxLength: 200, description: "search: required symbol or file query; returns at most 20 hits" },
        symbol: { type: "string", maxLength: 300, description: "node, callers, callees, impact, explore: required symbol from search" },
        depth: { type: "integer", minimum: 1, maximum: 5, description: "impact: default 3, max5. files depth4; explore max12 files" },
        space: { type: "string", description: "Space; session default, never rebinds" },
      },
      required: ["action", "graph_id"],
      additionalProperties: false,
    }
